so=[(m,s) for m in ms for s in (+1,-1)]
NS=10
def Vtab(B,C,nel=None):
    F4=441*C/35; F2=(441*B+5*F4)/9; F={2:F2,4:F4}
    V={}
    for a,b,c,d in itertools.product(range(NS),repeat=4):
        (ma,sa),(mb,sb),(mc,sc),(md,sd)=so[a],so[b],so[c],so[d]
