        v=np.array(vec,complex); P[:,:]+=coef*np.outer(v,v.conj())
    s2=1/np.sqrt(2)
    add([0,0,1,0,0],6*Dq)
    add([s2,0,0,0,s2],6*Dq)
    add([0,s2,0,-s2,0],-4*Dq)
    add([0,1/(1j*np.sqrt(2)),0,1/(1j*np.sqrt(2)),0],-4*Dq)
    add([1/(1j*np.sqrt(2)),0,0,0,-1/(1j*np.sqrt(2))],-4*Dq)
