            # S+S- : a+_up a_dn
            r,sg=apply([('c',iu),('a',idn)],st)
            if r is not None and r in idxs:
                M[idxs[r],j]+=sg*0.5  # S+S- /2 contribution (approx with per-orbital spin ops)
    return M

